/**
 * Stunt Racer 3D — all 30 levels (5 worlds × 6). Level data lives per world;
 * medal thresholds come from data/medals.js (generated by the bot's
 * reference runs — tools/simTest.mjs medals --write).
 */
import { LEVELS_SKY } from "./levelsSky.js";
import { LEVELS_DESERT } from "./levelsDesert.js";
import { LEVELS_OCEAN } from "./levelsOcean.js";
import { LEVELS_NEON } from "./levelsNeon.js";
import { LEVELS_EXTREME } from "./levelsExtreme.js";
import { MEDALS } from "./medals.js";

const RAW = [...LEVELS_SKY, ...LEVELS_DESERT, ...LEVELS_OCEAN, ...LEVELS_NEON, ...LEVELS_EXTREME];

export const LEVELS = RAW.map((l) => (MEDALS[l.id] ? { ...l, medals: MEDALS[l.id] } : l));
export const TOTAL_LEVELS = 30;
const BY_ID = new Map(LEVELS.map((l) => [l.id, l]));
export const getLevel = (id) => BY_ID.get(id) || null;
export const levelAvailable = (id) => BY_ID.has(id);
